/* libinference.so: export the public C API only (inference.h, tokenizer.h, sampler.h, vision.h, image.h, mrope.h, whisper.h, mel.h,
   qwen3tts*.h); the engine's internals
   (qwen_model_*, qmatvec_*, kernels) stay hidden. */
LIBINFERENCE_1 {
    global:
        inference_*;
        tokenizer_*;
        sampler_*;
        vision_*;
        image_*;
        mrope_*;
        whisper_*;
        mel_*;
        audio_*;
        qwen3tts_*;
    local:
        *;
};
